use harbor.signal;

fn entries() -> String {
    var result = "";
    var first = true;
    for sig in harbor.signal.signals() {
        let rendered = match sig {
            Calm => "calm",
            Gale(speed) => "gale:".concat(other: speed.to_text()),
            Fog(density) => "fog:".concat(other: density),
        };
        if first {
            result = rendered;
            first = false;
        } else {
            result = result.concat(other: ";");
            result = result.concat(other: rendered);
        }
    }
    result
}

use harbor.signal;

pub fn entries() -> String {
    var result = "";
