            Fog(density) => "fog:".concat(other: density),
        };
        if i > 0 {
            result = result.concat(other: ";");
        }
        result = result.concat(other: rendered);
        i = i + 1;
    }
    result
}

use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var first = true;
    for dish in board {
        if !first {
            io.write(text: ";")?;
        }
        galley.kitchen.serve(dish)?;
        first = false;
    }
    return Ok(unit);
}

