import stable.herd;
import stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = stable.herd.lineup();
    var result = "";
    var first = true;
    for pony in lineup {
        let fed = stable.herd.feed(pony: pony, scoops: 3);
        let entry = stable.ledger.render(pony: fed);
        if first {
            result = entry;
            first = false;
        } else {
            result = result.concat(other: ",");
            result = result.concat(other: entry);
        }
    }
    io.write(text: result)?;
    return Ok(unit);
}

